import{_ as l,a0 as d,w as o,s as c,ao as t,I as p,a1 as e,A as i,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"獻給 Debian 和 Ubuntu 用户的一組實用程序 | LCTT x X-CMD","titleTemplate":false,"description":"獻給 Debian 和 Ubuntu 用户的一組實用程序 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"獻給 Debian 和 Ubuntu 用户的一組實用程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"獻給 Debian 和 Ubuntu 用户的一組實用程序 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180523 A Set Of Useful Utilities For Debian And Ubuntu Users","title":"獻給 Debian 和 Ubuntu 用户的一組實用程序","tag":"201808","desc":""},"relativePath":"201808/20180523 A Set Of Useful Utilities For Debian And Ubuntu Users.md","filePath":"[post].md"}'),r={name:"201808/20180523 A Set Of Useful Utilities For Debian And Ubuntu Users.md"};function h(g,s,b,u,k,m){const n=d("Link");return o(),c("div",null,[s[17]||(s[17]=t(`<h1 id="獻給-debian-和-ubuntu-用户的一組實用程序" tabindex="-1">獻給 Debian 和 Ubuntu 用户的一組實用程序 <a class="header-anchor" href="#獻給-debian-和-ubuntu-用户的一組實用程序" aria-label="Permalink to “獻給 Debian 和 Ubuntu 用户的一組實用程序”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/05/debian-goodies-720x340.png" alt=""></p><p>你使用的是基於 Debian 的系統嗎？如果是，太好了！我今天在這裏給你帶來了一個好消息。先向 “Debian-goodies” 打個招呼，這是一組基於 Debian 系統（比如：Ubuntu、Linux Mint）的有用工具。這些實用工具提供了一些額外的有用的命令，這些命令在基於 Debian 的系統中默認不可用。通過使用這些工具，用户可以找到哪些程序佔用更多磁盤空間，更新系統後需要重新啓動哪些服務，在一個軟件包中搜索與模式匹配的文件，根據搜索字符串列出已安裝的包等等。在這個簡短的指南中，我們將討論一些有用的 Debian 的好東西。</p><h3 id="debian-goodies-–-給-debian-和-ubuntu-用户的實用程序" tabindex="-1">Debian-goodies – 給 Debian 和 Ubuntu 用户的實用程序 <a class="header-anchor" href="#debian-goodies-–-給-debian-和-ubuntu-用户的實用程序" aria-label="Permalink to “Debian-goodies – 給 Debian 和 Ubuntu 用户的實用程序”">​</a></h3><p>debian-goodies 包可以在 Debian 和其衍生的 Ubuntu 以及其它 Ubuntu 變體（如 Linux Mint）的官方倉庫中找到。要安裝 debian-goodies，只需簡單運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install debian-goodies</span></span></code></pre></div><p>debian-goodies 安裝完成後，讓我們繼續看一看一些有用的實用程序。</p><h4 id="_1、-checkrestart" tabindex="-1">1、 checkrestart <a class="header-anchor" href="#_1、-checkrestart" aria-label="Permalink to “1、 checkrestart”">​</a></h4><p>讓我從我最喜歡的 <code>checkrestart</code> 實用程序開始。安裝某些安全更新時，某些正在運行的應用程序可能仍然會使用舊庫。要徹底應用安全更新，你需要查找並重新啓動所有這些更新。這就是 <code>checkrestart</code> 派上用場的地方。該實用程序將查找哪些進程仍在使用舊版本的庫，然後，你可以重新啓動服務。</p><p>在進行庫更新後，要檢查哪些守護進程應該被重新啓動，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo checkrestart</span></span>
<span class="line"><span>[sudo] password for sk:</span></span>
<span class="line"><span>Found 0 processes using old versions of upgraded files</span></span></code></pre></div><p>由於我最近沒有執行任何安全更新，因此沒有顯示任何內容。</p><p>請注意，<code>checkrestart</code> 實用程序確實運行良好。但是，有一個名為 <code>needrestart</code> 的類似的新工具可用於最新的 Debian 系統。<code>needrestart</code> 的靈感來自 <code>checkrestart</code> 實用程序，它完成了同樣的工作。 <code>needrestart</code> 得到了積極維護，並支持容器（LXC、 Docker）等新技術。</p><p>以下是 <code>needrestart</code> 的特點：</p><ul><li>支持（但不要求）systemd</li><li>二進制程序的黑名單（例如：用於圖形顯示的顯示管理器）</li><li>嘗試檢測掛起的內核升級</li><li>嘗試檢測基於解釋器的守護進程所需的重啓（支持 Perl、Python、Ruby）</li><li>使用鈎子完全集成到 apt/dpkg 中</li></ul><p>它在默認倉庫中也可以使用。所以，你可以使用如下命令安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install needrestart</span></span></code></pre></div><p>現在，你可以使用以下命令檢查更新系統後需要重新啓動的守護程序列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo needrestart</span></span>
<span class="line"><span>Scanning processes...</span></span>
<span class="line"><span>Scanning linux images...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Running kernel seems to be up-to-date.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Failed to check for processor microcode upgrades.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No services need to be restarted.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No containers need to be restarted.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No user sessions are running outdated binaries.</span></span></code></pre></div><p>好消息是 Needrestart 同樣也適用於其它 Linux 發行版。例如，你可以從 Arch Linux 及其衍生版的 AUR 或者其它任何 AUR 幫助程序來安裝，就像下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yaourt -S needrestart</span></span></code></pre></div><p>在 Fedora：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install needrestart</span></span></code></pre></div><h4 id="_2、-check-enhancements" tabindex="-1">2、 check-enhancements <a class="header-anchor" href="#_2、-check-enhancements" aria-label="Permalink to “2、 check-enhancements”">​</a></h4><p><code>check-enhancements</code> 實用程序用於查找那些用於增強已安裝的包的軟件包。此實用程序將列出增強其它包但不是必須運行它的包。你可以通過 <code>-ip</code> 或 <code>–installed-packages</code> 選項來查找增強單個包或所有已安裝包的軟件包。</p><p>例如，我將列出增強 gimp 包功能的包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ check-enhancements gimp</span></span>
<span class="line"><span>gimp =&gt; gimp-data: Installed: (none) Candidate: 2.8.22-1</span></span>
<span class="line"><span>gimp =&gt; gimp-gmic: Installed: (none) Candidate: 1.7.9+zart-4build3</span></span>
<span class="line"><span>gimp =&gt; gimp-gutenprint: Installed: (none) Candidate: 5.2.13-2</span></span>
<span class="line"><span>gimp =&gt; gimp-help-ca: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-de: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-el: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-en: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-es: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-fr: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-it: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-ja: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-ko: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-nl: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-nn: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-pt: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-ru: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-sl: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-sv: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-plugin-registry: Installed: (none) Candidate: 7.20140602ubuntu3</span></span>
<span class="line"><span>gimp =&gt; xcftools: Installed: (none) Candidate: 1.0.7-6</span></span></code></pre></div><p>要列出增強所有已安裝包的，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ check-enhancements -ip</span></span>
<span class="line"><span>autoconf =&gt; autoconf-archive: Installed: (none) Candidate: 20170928-2</span></span>
<span class="line"><span>btrfs-progs =&gt; snapper: Installed: (none) Candidate: 0.5.4-3</span></span>
<span class="line"><span>ca-certificates =&gt; ca-cacert: Installed: (none) Candidate: 2011.0523-2</span></span>
<span class="line"><span>cryptsetup =&gt; mandos-client: Installed: (none) Candidate: 1.7.19-1</span></span>
<span class="line"><span>dpkg =&gt; debsig-verify: Installed: (none) Candidate: 0.18</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><h4 id="_3、-dgrep" tabindex="-1">3、 dgrep <a class="header-anchor" href="#_3、-dgrep" aria-label="Permalink to “3、 dgrep”">​</a></h4><p>顧名思義，<code>dgrep</code> 用於根據給定的正則表達式搜索制指定包的所有文件。例如，我將在 Vim 包中搜索包含正則表達式 “text” 的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dgrep &quot;text&quot; vim</span></span>
<span class="line"><span>Binary file /usr/bin/vim.tiny matches</span></span>
<span class="line"><span>/usr/share/doc/vim-tiny/copyright: that they must include this license text. You can also distribute</span></span>
<span class="line"><span>/usr/share/doc/vim-tiny/copyright: include this license text. You are also allowed to include executables</span></span>
<span class="line"><span>/usr/share/doc/vim-tiny/copyright: 1) This license text must be included unmodified.</span></span>
<span class="line"><span>/usr/share/doc/vim-tiny/copyright: text under a) applies to those changes.</span></span>
<span class="line"><span>/usr/share/doc/vim-tiny/copyright: context diff. You can choose what license to use for new code you</span></span>
<span class="line"><span>/usr/share/doc/vim-tiny/copyright: context diff will do. The e-mail address to be used is</span></span>
<span class="line"><span>/usr/share/doc/vim-tiny/copyright: On Debian systems, the complete text of the GPL version 2 license can be</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p><code>dgrep</code> 支持大多數 <code>grep</code> 的選項。參閲以下指南以瞭解 <code>grep</code> 命令。</p>`,33)),p("ul",null,[p("li",null,[e(n,{href:"https://www.ostechnix.com/the-grep-command-tutorial-with-examples-for-beginners/"},{default:i(()=>[...s[0]||(s[0]=[a("獻給初學者的 Grep 命令教程",-1)])]),_:1})])]),s[18]||(s[18]=t(`<h4 id="_4、-dglob" tabindex="-1">4、 dglob <a class="header-anchor" href="#_4、-dglob" aria-label="Permalink to “4、 dglob”">​</a></h4><p><code>dglob</code> 實用程序生成與給定模式匹配的包名稱列表。例如，找到與字符串 “vim” 匹配的包列表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dglob vim</span></span>
<span class="line"><span>vim-tiny:amd64</span></span>
<span class="line"><span>vim:amd64</span></span>
<span class="line"><span>vim-common:all</span></span>
<span class="line"><span>vim-runtime:all</span></span></code></pre></div><p>默認情況下，<code>dglob</code> 將僅顯示已安裝的軟件包。如果要列出所有包（包括已安裝的和未安裝的），使用 <code>-a</code> 標誌。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dglob vim -a</span></span></code></pre></div><h4 id="_5、-debget" tabindex="-1">5、 debget <a class="header-anchor" href="#_5、-debget" aria-label="Permalink to “5、 debget”">​</a></h4><p><code>debget</code> 實用程序將在 APT 的資料庫中下載一個包的 .deb 文件。請注意，它只會下載給定的包，不包括依賴項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ debget nano</span></span>
<span class="line"><span>Get:1 http://in.archive.ubuntu.com/ubuntu bionic/main amd64 nano amd64 2.9.3-2 [231 kB]</span></span>
<span class="line"><span>Fetched 231 kB in 2s (113 kB/s)</span></span></code></pre></div><h4 id="_6、-dpigs" tabindex="-1">6、 dpigs <a class="header-anchor" href="#_6、-dpigs" aria-label="Permalink to “6、 dpigs”">​</a></h4><p>這是此次集合中另一個有用的實用程序。<code>dpigs</code> 實用程序將查找並顯示那些佔用磁盤空間最多的已安裝包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dpigs</span></span>
<span class="line"><span>260644 linux-firmware</span></span>
<span class="line"><span>167195 linux-modules-extra-4.15.0-20-generic</span></span>
<span class="line"><span>75186 linux-headers-4.15.0-20</span></span>
<span class="line"><span>64217 linux-modules-4.15.0-20-generic</span></span>
<span class="line"><span>55620 snapd</span></span>
<span class="line"><span>31376 git</span></span>
<span class="line"><span>31070 libicu60</span></span>
<span class="line"><span>28420 vim-runtime</span></span>
<span class="line"><span>25971 gcc-7</span></span>
<span class="line"><span>24349 g++-7</span></span></code></pre></div><p>如你所見，linux-firmware 包占用的磁盤空間最多。默認情況下，它將顯示佔用磁盤空間的 <strong>前 10 個</strong>包。如果要顯示更多包，例如 20 個，運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dpigs -n 20</span></span></code></pre></div><h4 id="_7-debman" tabindex="-1">7. debman <a class="header-anchor" href="#_7-debman" aria-label="Permalink to “7. debman”">​</a></h4><p><code>debman</code> 實用程序允許你輕鬆查看二進制文件 .deb 中的手冊頁而不提取它。你甚至不需要安裝 .deb 包。以下命令顯示 nano 包的手冊頁。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ debman -f nano_2.9.3-2_amd64.deb nano</span></span></code></pre></div><p>如果你沒有 .deb 軟件包的本地副本，使用 <code>-p</code> 標誌下載並查看包的手冊頁。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ debman -p nano nano</span></span></code></pre></div><p><strong>建議閲讀：</strong></p>`,19)),p("ul",null,[p("li",null,[e(n,{href:"https://www.ostechnix.com/3-good-alternatives-man-pages-every-linux-user-know/"},{default:i(()=>[...s[1]||(s[1]=[a("每個 Linux 用户都應該知道的 3 個 man 的替代品",-1)])]),_:1})])]),s[19]||(s[19]=t(`<h4 id="_8、-debmany" tabindex="-1">8、 debmany <a class="header-anchor" href="#_8、-debmany" aria-label="Permalink to “8、 debmany”">​</a></h4><p>安裝的 Debian 包不僅包含手冊頁，還包括其它文件，如確認、版權和自述文件等。<code>debmany</code> 實用程序允許你查看和讀取那些文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ debmany vim</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/05/debmany.png" alt=""></p><p>使用方向鍵選擇要查看的文件，然後按回車鍵查看所選文件。按 <code>q</code> 返回主菜單。</p><p>如果未安裝指定的軟件包，<code>debmany</code> 將從 APT 資料庫下載並顯示手冊頁。應安裝 <code>dialog</code> 包來閲讀手冊頁。</p><h4 id="_9、-popbugs" tabindex="-1">9、 popbugs <a class="header-anchor" href="#_9、-popbugs" aria-label="Permalink to “9、 popbugs”">​</a></h4><p>如果你是開發人員，<code>popbugs</code> 實用程序將非常有用。它將根據你使用的包顯示一個定製的發佈關鍵 bug 列表（使用 popularity-contest 數據）。對於那些不關心的人，popularity-contest 包設置了一個 cron （定時）任務，它將定期匿名向 Debian 開發人員提交有關該系統上最常用的 Debian 軟件包的統計信息。這些信息有助於 Debian 做出決定，例如哪些軟件包應該放在第一張 CD 上。它還允許 Debian 改進未來的發行版本，以便為新用户自動安裝最流行的軟件包。</p><p>要生成嚴重 bug 列表並在默認 Web 瀏覽器中顯示結果，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ popbugs</span></span></code></pre></div><p>此外，你可以將結果保存在文件中，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ popbugs --output=bugs.txt</span></span></code></pre></div><h4 id="_10、-which-pkg-broke" tabindex="-1">10、 which-pkg-broke <a class="header-anchor" href="#_10、-which-pkg-broke" aria-label="Permalink to “10、 which-pkg-broke”">​</a></h4><p>此命令將顯示給定包的所有依賴項以及安裝每個依賴項的時間。通過使用此信息，你可以在升級系統或軟件包之後輕鬆找到哪個包可能會在什麼時間損壞了另一個包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ which-pkg-broke vim</span></span>
<span class="line"><span>Package &lt;debconf-2.0&gt; has no install time info</span></span>
<span class="line"><span>debconf Wed Apr 25 08:08:40 2018</span></span>
<span class="line"><span>gcc-8-base:amd64 Wed Apr 25 08:08:41 2018</span></span>
<span class="line"><span>libacl1:amd64 Wed Apr 25 08:08:41 2018</span></span>
<span class="line"><span>libattr1:amd64 Wed Apr 25 08:08:41 2018</span></span>
<span class="line"><span>dpkg Wed Apr 25 08:08:41 2018</span></span>
<span class="line"><span>libbz2-1.0:amd64 Wed Apr 25 08:08:41 2018</span></span>
<span class="line"><span>libc6:amd64 Wed Apr 25 08:08:42 2018</span></span>
<span class="line"><span>libgcc1:amd64 Wed Apr 25 08:08:42 2018</span></span>
<span class="line"><span>liblzma5:amd64 Wed Apr 25 08:08:42 2018</span></span>
<span class="line"><span>libdb5.3:amd64 Wed Apr 25 08:08:42 2018</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><h4 id="_11、-dhomepage" tabindex="-1">11、 dhomepage <a class="header-anchor" href="#_11、-dhomepage" aria-label="Permalink to “11、 dhomepage”">​</a></h4><p><code>dhomepage</code> 實用程序將在默認 Web 瀏覽器中顯示給定包的官方網站。例如，以下命令將打開 Vim 編輯器的主頁。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dhomepage vim</span></span></code></pre></div><p>這就是全部了。Debian-goodies 是你武器庫中必備的工具。即使我們不經常使用所有這些實用程序，但它們值得學習，我相信它們有時會非常有用。</p><p>我希望這很有用。更多好東西要來了。敬請關注！</p><p>乾杯!</p><hr>`,22)),p("p",null,[s[3]||(s[3]=a("via: ",-1)),e(n,{href:"https://www.ostechnix.com/debian-goodies-a-set-of-useful-utilities-for-debian-and-ubuntu-users/"},{default:i(()=>[...s[2]||(s[2]=[a("https://www.ostechnix.com/debian-goodies-a-set-of-useful-utilities-for-debian-and-ubuntu-users/",-1)])]),_:1})]),p("p",null,[s[8]||(s[8]=a("作者：",-1)),e(n,{href:"https://www.ostechnix.com/author/sk/"},{default:i(()=>[...s[4]||(s[4]=[a("SK",-1)])]),_:1}),s[9]||(s[9]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[5]||(s[5]=[a("lujun9972",-1)])]),_:1}),s[10]||(s[10]=a(" 譯者：",-1)),e(n,{href:"https://github.com/MjSeven"},{default:i(()=>[...s[6]||(s[6]=[a("MjSeven",-1)])]),_:1}),s[11]||(s[11]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[7]||(s[7]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[14]||(s[14]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[12]||(s[12]=[a("LCTT",-1)])]),_:1}),s[15]||(s[15]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[13]||(s[13]=[a("Linux中國",-1)])]),_:1}),s[16]||(s[16]=a(" 榮譽推出",-1))])])}const x=l(r,[["render",h]]);export{C as __pageData,x as default};
